uint32_t reverseBits(uint32_t n) {
    uint32_t result = 0;
    for (int i = 0; i < 32; ++i) {
        result = (result << 1) | (n & 1);                   // append the lowest bit of n
        n >>= 1;
    }
    return result;
}

public int reverseBits(int n) {
    int result = 0;
    for (int i = 0; i < 32; i++) {
        result = (result << 1) | (n & 1);               // append the lowest bit of n
        n >>>= 1;                                       // unsigned shift so the sign bit is not copied
    }
    return result;
}
